import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 2048, "warp_size": 32}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_SIZE": 4096, "warp_size": 32}, num_warps=8, num_stages=2),
        triton.Config(
            {"BLOCK_SIZE": 8192, "warp_size": 32}, num_warps=16, num_stages=2
        ),
        triton.Config(
            {"BLOCK_SIZE": 4096, "warp_size": 16}, num_warps=16, num_stages=2
        ),
        triton.Config(
            {"BLOCK_SIZE": 8192, "warp_size": 16}, num_warps=16, num_stages=2
        ),
    ],
    key=["N"],
)
@triton.jit
def instance_norm_kernel(
    x_ptr,
    out_ptr,
    N,
    eps,
    BLOCK_SIZE: tl.constexpr,
    warp_size: tl.constexpr,
):
    pid = tl.program_id(0)
    base = pid.to(tl.int64) * N

    sum_acc = tl.zeros((BLOCK_SIZE,), dtype=tl.float32)
    sq_acc = tl.zeros((BLOCK_SIZE,), dtype=tl.float32)
    for start in range(0, N, BLOCK_SIZE):
        offs = start + tl.arange(0, BLOCK_SIZE)
        mask = offs < N
        x = tl.load(x_ptr + base + offs, mask=mask, other=0.0)
        sum_acc += x
        sq_acc += x * x

    total_sum = tl.sum(sum_acc, axis=0)
    total_sq = tl.sum(sq_acc, axis=0)
    mean = total_sum / N
    var = total_sq / N - mean * mean
    inv_std = 1.0 / tl.sqrt(var + eps)

    for start in range(0, N, BLOCK_SIZE):
        offs = start + tl.arange(0, BLOCK_SIZE)
        mask = offs < N
        x = tl.load(x_ptr + base + offs, mask=mask, other=0.0)
        out = (x - mean) * inv_std
        tl.store(out_ptr + base + offs, out, mask=mask)


class Model(nn.Module):
    def __init__(self, num_features: int):
        super(Model, self).__init__()
        self.num_features = num_features
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        B, C, H, W = x.shape
        N = H * W
        x_flat = x.contiguous().view(B * C, N)
        out = torch.empty_like(x_flat)
        grid = (B * C,)
        instance_norm_kernel[grid](
            x_flat,
            out,
            N,
            self.eps,
        )
        return out.view(B, C, H, W)
